def ste_train(w, x, codebook, lr, steps):
    def q(v):
        best = None
        val = 0
        for e in codebook:
            d = (v - e) ** 2
            if best is None or d < best - 1e-12:
                best = d
                val = e
        return val
    for t in range(steps):
        zq = q(w * x)
        w = w - lr * 2 * (zq - x) * x
    zq = q(w * x)
    return [round(w, 6), round((x - zq) ** 2, 6)]

