practice.solution:
def kmeans_step(points, centers):
    k = len(centers)
    d = len(centers[0])
    sums = [[0.0] * d for i in range(k)]
    cnt = [0] * k
    for p in points:
        best = None
        arg = 0
        for i in range(k):
            dist = sum((a - b) ** 2 for a, b in zip(p, centers[i]))
            if best is None or dist < best - 1e-12:
                best = dist
                arg = i
        cnt[arg] += 1
        for j in range(d):
            sums[arg][j] += p[j]
    out = []
    for i in range(k):
        if cnt[i] == 0:
            out.append(list(centers[i]))
        else:
            out.append([round(s / cnt[i], 6) for s in sums[i]])
    return out

