practice.solution:
def train_bigram(seqs, k, alpha):
    c = [[0] * k for i in range(k)]
    for s in seqs:
        for a, b in zip(s[:-1], s[1:]):
            c[a][b] += 1
    T = []
    for a in range(k):
        tot = sum(c[a]) + alpha * k
        T.append([round((c[a][b] + alpha) / tot, 6) for b in range(k)])
    return T

