practice.solution:
def choose_k(cands, max_bits):
    best = None
    arg = 0
    for k, err, bits in cands:
        if bits <= max_bits:
            if best is None or err < best - 1e-12 or (abs(err - best) <= 1e-12 and k < arg):
                best = err
                arg = k
    return arg
